// ============================================================================
// Send metadata – gross list
// ----------------------------------------------------------------------------
// Purpose:
//   Fetch all points from persistent global context under
//   genericGrossList[deviceKey].nodeff[controllerKey].points and output them
//   in msg.payload. 
//
// Inputs (optional overrides via msg):
//   - msg.deviceKey       (default: 'Git')
//   - msg.controllerKey   (default: 'Lindinspect_controller')
//
// Reads:
//   global (persistent): genericGrossList
//
// Outputs:
//   - msg.payload : point[] (deep-cloned to avoid downstream mutation)
//   - msg.meta    : { deviceKey, controllerKey, path, count, updatedAt }
//
// Notes:
//   - Deep cloning prevents accidental mutation of global state in later nodes.
//   - Status is green when points exist; red when none are found.
// ============================================================================

const STORE = 'persistent';

// Resolve keys from msg (allow per-call overrides)
const deviceKey = msg.deviceKey || 'Git';
const controllerKey = msg.controllerKey || 'Lindinspect_controller';

// Read inventory from global context (defensive default)
const inventory = global.get('genericGrossList', STORE) || {};

// Safely access points array
const points = Array.isArray(inventory?.[deviceKey]?.nodeff?.[controllerKey]?.points)
  ? inventory[deviceKey].nodeff[controllerKey].points
  : [];

// Deep clone to avoid downstream mutation of global state
let safePoints;
try {
  safePoints = JSON.parse(JSON.stringify(points));
} catch (e) {
  // Fallback: shallow copy if cloning fails
  safePoints = points.slice();
}

// Emit data
msg.payload = safePoints;

// Status for quick visual feedback
node.status({
  fill: safePoints.length ? 'green' : 'red',
  shape: 'dot',
  text: safePoints.length ? `points: ${safePoints.length}` : 'no points found'
});

return msg;
